"""Foreign-exchange conversion into a merchant's settlement currency."""

from __future__ import annotations

import bisect
import logging
from datetime import date
from decimal import Decimal

from .money import exponent, round_half_up, to_minor

log = logging.getLogger(__name__)


class RateTable:
    """Daily rates per ordered currency pair."""

    def __init__(self, rows: list[dict]):
        self._dates: dict[tuple[str, str], list[str]] = {}
        self._rates: dict[tuple[tuple[str, str], str], Decimal] = {}
        for r in rows:
            pair = (r["from_currency"], r["to_currency"])
            self._rates[(pair, r["date"])] = Decimal(r["rate"])
            self._dates.setdefault(pair, []).append(r["date"])
        for dates in self._dates.values():
            dates.sort()

    def lookup(self, from_ccy: str, to_ccy: str, on: date) -> Decimal:
        """Return the rate to use for converting on date ``on``.

        The rate comes from the fx_rates.csv row with from_currency = currency,
        to_currency = settlement currency, and the latest date that is on or before
        the settlement date.
        """
        pair = (from_ccy, to_ccy)
        if pair not in self._dates:
            raise LookupError(f"no rates for {from_ccy}->{to_ccy}")
        dates = self._dates[pair]
        on_str = on.isoformat()
        # Find the latest date on or before on_str
        i = bisect.bisect_right(dates, on_str) - 1
        if i < 0:
            raise LookupError(f"no {from_ccy}->{to_ccy} rate usable on {on_str}")
        return self._rates[(pair, dates[i])]

    def pairs(self) -> list[tuple[str, str]]:
        """All currency pairs present in the table, sorted."""
        return sorted(self._dates)

    def __len__(self) -> int:
        return len(self._rates)


def convert(amount: str, currency: str, settle_ccy: str, rates: RateTable, on: date) -> int:
    """Express ``amount`` of ``currency`` in minor units of ``settle_ccy``.

    R7. Conversion:
    - If currency equals the settlement currency, settled_minor = amount_minor.
    - Otherwise settled_minor = round_half_up(amount x rate x 10^s), where s is
      the exponent of the settlement currency and rate comes from fx_rates.csv.
    """
    if currency == settle_ccy:
        return to_minor(amount, currency)
    rate = rates.lookup(currency, settle_ccy, on)
    s = exponent(settle_ccy)
    return round_half_up(Decimal(amount) * rate * (10 ** s))
